// Input validation and security checks
const input = $input.first().json;

// Validate required fields
if (!input.task || typeof input.task !== 'string' || input.task.trim().length === 0) {
  return {
    json: {
      success: false,
      error: 'Invalid input: task is required and must be a non-empty string',
      agentType: 'code_interpreter',
      errorCode: 'INVALID_INPUT'
    }
  };
}

// Security: Block dangerous patterns
const dangerousPatterns = [
  /os\.system/i,
  /subprocess\./i,
  /eval\(/i,
  /exec\(/i,
  /open\(['"][^'"]*\/(etc|proc|sys)/i,
  /import\s+ctypes/i,
  /\.__class__/,
  /\.__base__/,
  /\.__subclasses__/
];

for (const pattern of dangerousPatterns) {
  if (pattern.test(input.task)) {
    return {
      json: {
        success: false,
        error: 'Security violation: potentially dangerous code pattern detected',
        agentType: 'code_interpreter',
        errorCode: 'SECURITY_VIOLATION'
      }
    };
  }
}

const sanitizedTask = input.task.trim().slice(0, 10000); // Limit task length

return {
  json: {
    task: sanitizedTask,
    sessionId: input.sessionId || $execution.id,
    startTime: Date.now(),
    metadata: {
      inputLength: sanitizedTask.length,
      executionId: $execution.id
    }
  }
};

// Format successful output
const input = $('Validate Input').first().json;
const result = $input.first().json;

const executionTime = Date.now() - (input.startTime || Date.now());

// Parse execution results
let executionResult = null;
let generatedFiles = [];
let variables = {};

try {
  if (result.intermediateSteps) {
    for (const step of result.intermediateSteps) {
      if (step.observation) {
        // Capture execution output
        if (typeof step.observation === 'string') {
          executionResult = step.observation;
        } else if (step.observation.output) {
          executionResult = step.observation.output;
        }
        // Capture generated files
        if (step.observation.files) {
          generatedFiles = generatedFiles.concat(step.observation.files);
        }
      }
    }
  }

  // Try to extract structured data from output
  if (result.output) {
    const jsonMatch = result.output.match(/```json\n([\s\S]*?)\n```/);
    if (jsonMatch) {
      try {
        variables = JSON.parse(jsonMatch[1]);
      } catch (e) {}
    }
  }
} catch (e) {
  // Non-critical parsing error
}

return {
  json: {
    success: true,
    agentType: 'code_interpreter',
    output: result.output || 'Code executed successfully',
    executionResult,
    generatedFiles,
    variables,
    metadata: {
      executionTime,
      toolCalls: (result.intermediateSteps || []).length,
      executionId: input.metadata?.executionId
    }
  }
};

// Handle validation/security error
const input = $input.first().json;

return {
  json: {
    success: false,
    agentType: 'code_interpreter',
    error: input.error || 'Validation failed',
    errorCode: input.errorCode || 'VALIDATION_ERROR',
    output: null,
    metadata: {
      executionId: $execution.id
    }
  }
};
